-- Generated by contracts/compile.py from contracts/partners.yml (rule P-12). Do not edit.
-- Titles on the scorecard add up to titles actually submitted.
{{ config(tags=['contract', 'contract_partners'], severity='error',
          meta={'contract': 'partners', 'rule': 'P-12'}) }}

with contract_side as (
    select sum(titles_submitted) as value from {{ ref('mart_partner_publishing') }}
),
reference_side as (
    select count(distinct title_id) as value from {{ ref('fct_submission') }}
)
select c.value as contract_value, r.value as reference_value
from contract_side c cross join reference_side r
where c.value is null or r.value is null or abs(c.value - r.value) > 0
